<script lang="ts">import type { Snippet } from 'svelte'; import { cn } from '../../utils.js'; import { provideSandboxTabsContext } from './context.svelte.js'; let { defaultValue = '', value = $bindable(defaultValue), class: className = '', children, onvaluechange, onValueChange, ...rest }: { value?: string; defaultValue?: string; class?: string; children?: Snippet; onvaluechange?: (value: string) => void; onValueChange?: (value: string) => void; [key: string]: unknown } = $props(); const id = $props.id(); function setValue(next: string): void { value = next; onvaluechange?.(next); if (onValueChange !== onvaluechange) onValueChange?.(next); } function partId(kind: 'tab' | 'panel', next: string): string { return `${id}-${kind}-${encodeURIComponent(next)}`; } provideSandboxTabsContext({ get value() { return value; }, setValue, tabId(next) { return partId('tab', next); }, panelId(next) { return partId('panel', next); } });</script>
<div {...rest} class={cn('w-full', className)} data-value={value}>{@render children?.()}</div>
